    const hitboxTypeObj = parseValue(hitboxType, 'enum')
    assertClientLiteralValue(hitboxTypeObj, 'triggerHitboxAtSpecificLocation.hitboxType')
    const scaleOfCuboidHitboxObj = parseValue(scaleOfCuboidHitbox, 'vec3')
