  assemblyDictionary<K extends DictKeyType, V extends DictValueType>(
    pairs: {
      k: RuntimeParameterValueTypeMap[K]
      v: RuntimeParameterValueTypeMap[V]
    }[]
  ): ReadonlyDict<K, V> {
    if (pairs.length === 0) throw new Error('Pairs cannot be empty')

    if (pairs.length > 50) throw new Error('Pairs cannot be more than 50')

    const keys = pairs.map((p) => p.k)
    const keyType = matchTypes(
      ['int', 'str', 'entity', 'guid', 'faction', 'config_id', 'prefab_id'],
      ...keys
    )
    const values = pairs.map((p) => p.v)
    const valueType = matchTypes(
      [
        'float',
        'int',
        'bool',
        'config_id',
        'entity',
        'faction',
        'guid',
        'prefab_id',
        'str',
        'vec3'
      ],
      ...values
    )

    const key0to49Obj = keys.map((k) => parseValue(k, keyType))

    const isValueTypeList = values[0] instanceof list
    const value0to49Obj = isValueTypeList
      ? values.map((v) =>
          parseValue(v, (valueType + '_list') as keyof CommonLiteralValueListTypeMap)
        )
      : values.map((v) => parseValue(v, valueType))

    const kv0to49Args = key0to49Obj.flatMap((k, i) => [k, value0to49Obj[i]])

    const ref = this.registry.registerNode({
      id: 0,
      type: 'data',
      nodeType: 'assembly_dictionary',
      args: kv0to49Args
    })
    const retValueType = isValueTypeList ? ((valueType + '_list') as DictValueType) : valueType
    const ret = new dict(keyType, retValueType) as dict<K, V>
    ret.markPin(ref, 'dictionary', 0)
    return ret
  }

  /**
   * Assembles multiple Input Parameters of the same type (up to 10) into a single List
   *
   * 拼装列表: 将多个类型相同的入参(至多10个)拼装为一个列表
   *
   * @param _0to9 Assemble up to 10 parameters into a list
   *
   * 0~9: 将至多10个参数拼装为一个列表
   *
   * @returns The assembled list
   *
   * 列表: 拼装成的列表
   */
  assemblyList(_0to9: FloatValue[]): number[]
  assemblyList(_0to9: FloatValue[], type: 'float'): number[]
  assemblyList(_0to9: IntValue[]): bigint[]
  assemblyList(_0to9: IntValue[], type: 'int'): bigint[]
  assemblyList(_0to9: BoolValue[]): boolean[]
  assemblyList(_0to9: BoolValue[], type: 'bool'): boolean[]
  assemblyList(_0to9: ConfigIdValue[]): configId[]
  assemblyList(_0to9: ConfigIdValue[], type: 'config_id'): configId[]
  assemblyList(_0to9: EntityValue[]): clientEntity<'creation_status', Mode>[]
  assemblyList(_0to9: EntityValue[], type: 'entity'): clientEntity<'creation_status', Mode>[]
  assemblyList(_0to9: FactionValue[]): faction[]
  assemblyList(_0to9: FactionValue[], type: 'faction'): faction[]
  assemblyList(_0to9: GuidValue[]): guid[]
  assemblyList(_0to9: GuidValue[], type: 'guid'): guid[]
  assemblyList(_0to9: PrefabIdValue[]): prefabId[]
  assemblyList(_0to9: PrefabIdValue[], type: 'prefab_id'): prefabId[]
  assemblyList(_0to9: StrValue[]): string[]
  assemblyList(_0to9: StrValue[], type: 'str'): string[]
  assemblyList(_0to9: Vec3Value[]): vec3[]
  assemblyList(_0to9: Vec3Value[], type: 'vec3'): vec3[]
  assemblyList<
    T extends
      | 'float'
      | 'int'
      | 'bool'
      | 'config_id'
      | 'entity'
      | 'faction'
      | 'guid'
      | 'prefab_id'
      | 'str'
      | 'vec3'
  >(
    _0to9: RuntimeParameterValueTypeMap[T][],
    type?: T
  ): ClientRuntimeReturnValueTypeMap<'creation_status', Mode>[`${T}_list`] {
    if (_0to9.length === 0 || _0to9.length > 10) {
      throw new Error(`[error] assemblyList: expected 1-10 elements, got ${_0to9.length}`)
    }
    let genericType = matchTypes(
      [
        'float',
        'int',
        'bool',
        'config_id',
        'entity',
        'faction',
        'guid',
        'prefab_id',
        'str',
        'vec3'
      ],
      ..._0to9
    )
    if (type) genericType = type
    const elementObjs = _0to9.map((v) => parseValue(v, genericType))
    const ref = this.registry.registerNode({
      id: 0,
      type: 'data',
      nodeType: 'assembly_list',
      args: elementObjs
    })
    const ret = new list(genericType)
    ret.markPin(ref, 'list', 0)
    return ret as unknown as ClientRuntimeReturnValueTypeMap<'creation_status', Mode>[`${T}_list`]
  }

